async function fetchUserLocksOnChain(owner, chainId, publicClient) {
  try {
    const votingEscrowAddress = getContractAddress(chainId, "VotingEscrow");
    const votingEscrowAbi = getContractAbi(chainId, "VotingEscrow");
    if (!votingEscrowAddress || !votingEscrowAbi) {
      console.error("VotingEscrow contract not found for chain", chainId);
      return [];
    }
    const balance = await publicClient.readContract({
      address: votingEscrowAddress,
      abi: votingEscrowAbi,
      functionName: "balanceOf",
      args: [owner]
    });
    if (balance === 0n) {
      return [];
    }
    const tokenIdCalls = [];
    for (let i = 0; i < Number(balance); i++) {
      tokenIdCalls.push({
        address: votingEscrowAddress,
        abi: votingEscrowAbi,
        functionName: "ownerToNFTokenIdList",
        args: [owner, BigInt(i)]
      });
    }
    const tokenIdResults = await publicClient.multicall({
      allowFailure: true,
      contracts: tokenIdCalls
    });
    const tokenIds = tokenIdResults.filter((result) => result.status === "success").map((result) => result.result);
    const lockDataCalls = tokenIds.flatMap((tokenId) => [
      {
        address: votingEscrowAddress,
        abi: votingEscrowAbi,
        functionName: "locked",
        args: [tokenId]
      },
      {
        address: votingEscrowAddress,
        abi: votingEscrowAbi,
        functionName: "balanceOfNFT",
        args: [tokenId]
      },
      {
        address: votingEscrowAddress,
        abi: votingEscrowAbi,
        functionName: "escrowType",
        args: [tokenId]
      }
    ]);
    const lockDataResults = await publicClient.multicall({
      allowFailure: true,
      contracts: lockDataCalls
    });
    const locks = [];
    tokenIds.forEach((tokenId, index) => {
      const baseIndex = index * 3;
      const lockedResult = lockDataResults[baseIndex];
      const votingPowerResult = lockDataResults[baseIndex + 1];
      const escrowTypeResult = lockDataResults[baseIndex + 2];
      if (lockedResult?.status !== "success" || votingPowerResult?.status !== "success" || escrowTypeResult?.status !== "success") {
        console.warn(`Failed to fetch complete lock data for token ID ${tokenId}`);
        return;
      }
      const lockedData = lockedResult.result;
      const votingPower = votingPowerResult.result;
      const escrowType = escrowTypeResult.result;
      const tokenIdString = tokenId.toString();
      const isActualRelayNft = Object.keys(MANAGED_VAULT_REWARD_CONFIGS).includes(tokenIdString);
      locks.push({
        id: tokenIdString,
        owner: owner.toLowerCase(),
        amount: lockedData.amount.toString(),
        lockEnd: lockedData.end.toString(),
        lockStart: "0",
        // Not available on-chain, set to 0
        votingPower: votingPower.toString(),
        permanent: lockedData.isPermanent,
        managed: isActualRelayNft
      });
    });
    return locks;
  } catch (error) {
    console.error("Failed to fetch veABX locks on-chain:", error);
    return [];
  }
}
