      if (votingPowerResult?.status === "success") {
        const votingPower = votingPowerResult.result;
        if (typeof votingPower === "bigint") {
          partial.votingPower = votingPower.toString();
        }
      }
      if (Object.keys(partial).length > 0) {
        updates.set(lock.id, partial);
      }
