export function useVeABXUserLocks(owner, enabled = true, chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["veabx-user-locks", owner?.toLowerCase(), chainId],
    queryFn: async () => {
      if (!owner || !publicClient) return [];
      const locks = await fetchUserLocksOnChain(owner, chainId, publicClient);
      return enhanceLocksWithOnChainData(locks, chainId, publicClient);
    },
    enabled: enabled && !!owner,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    staleTime: 15e3
    // Consider data stale after 15 seconds
  });
}
export function useVeABXLock(lockId, enabled = true, chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["veabx-lock", lockId, chainId],
    queryFn: async () => {
      if (!lockId || !publicClient) return null;
      const locks = await fetchSpecificLocksOnChain([lockId], chainId, publicClient);
      if (locks.length === 0) return null;
      const [enhancedLock] = await enhanceLocksWithOnChainData(locks, chainId, publicClient);
      return enhancedLock ?? locks[0];
    },
    enabled: enabled && !!lockId && !!publicClient,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    staleTime: 15e3
    // Consider data stale after 15 seconds
  });
}
