export function useManagedVeABXRelays(enabled = true, chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["veabx-managed-relays", chainId],
    queryFn: async () => {
      if (!publicClient) return [];
      const managedTokenIds = Object.keys(MANAGED_VAULT_REWARD_CONFIGS);
      const locks = await fetchSpecificLocksOnChain(managedTokenIds, chainId, publicClient);
      return enhanceLocksWithOnChainData(locks, chainId, publicClient);
    },
    enabled: enabled && !!publicClient,
    refetchInterval: 6e4,
    staleTime: 3e4
  });
}
